SELECT jsonb_build_object('profile',to_jsonb(u)-'id'-'alias','now',event_time(),'year',(select year from season),'day',event_day(event_time()),'wheelDay',wheel_day(event_time()),'game',game_at(event_time()),'opened',coalesce((select jsonb_agg(day order by day) from doors where uid=u.id),'[]'),'spins',coalesce((select jsonb_object_agg(day,reward) from spins where uid=u.id),'{}'),'tickets',coalesce((select jsonb_agg(to_jsonb(t)-'uid' order by id desc) from tickets t where uid=u.id and valid),'[]'),'attempts',coalesce((select jsonb_agg(to_jsonb(a)-'uid'-'scene'-'pressed' order by game,slot) from attempts a where uid=u.id),'[]'),'commitment',(select commitment from season)) FROM users u WHERE id=$1
